  "inlineSchema": "// INMOVISIÓN 360 SUITE — Prisma Schema\n// Motor: SQLite (archivo local, sin servidor)\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"sqlite\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ── Enums (SQLite no soporta enum nativo, se usan String) ────\n// Rol:         arrendador | inquilino | admin\n// PlanId:      free | starter | professional | enterprise\n// ListingType: rent | sale | rent_sale | vacation\n// VisitaEstado:pendiente | confirmada | cancelada\n// PagoEstado:  pendiente | pagado | vencido\n// LeadEstado:  new | contactado | interesado | visita_agendada | lost\n\nmodel Usuario {\n  id             String    @id @default(cuid())\n  nombre         String\n  apellido       String    @default(\"\")\n  email          String    @unique\n  password       String? // ← ahora opcional (usuarios Google no tienen)\n  googleId       String?   @unique // ← nuevo\n  provider       String    @default(\"local\") // ← nuevo: \"local\" | \"google\"\n  perfilCompleto Boolean   @default(true) // ← nuevo: false = falta completar rol/nombre\n  rol            String    @default(\"inquilino\")\n  plan           String    @default(\"free\")\n  telefono       String?\n  verified       Boolean   @default(false)\n  createdAt      DateTime  @default(now())\n  updatedAt      DateTime  @updatedAt\n  deletedAt      DateTime?\n\n  propiedades   Propiedad[]    @relation(\"OwnerProps\")\n  visitas       Visitas[]      @relation(\"InquilinoVisitas\")\n  mensajesEnv   Mensaje[]      @relation(\"MensajesDe\")\n  mensajesRec   Mensaje[]      @relation(\"MensajesPara\")\n  leads         Lead[]         @relation(\"OwnerLeads\")\n  pagosOwner    Pago[]         @relation(\"OwnerPagos\")\n  pagosInq      Pago[]         @relation(\"InquilinoPagos\")\n  favoritos     Favorito[]\n  suscripcion   Suscripcion?\n  refreshTokens RefreshToken[]\n\n  @@map(\"usuarios\")\n}\n\nmodel RefreshToken {\n  id        String   @id @default(cuid())\n  token     String   @unique\n  userId    String\n  revoked   Boolean  @default(false)\n  expiresAt DateTime\n  createdAt DateTime @default(now())\n\n  user Usuario @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"refresh_tokens\")\n}\n\nmodel Plan {\n  id       String @id // free | starter | professional | enterprise\n  nombre   String\n  precio   Int    @default(0)\n  propsMax Int? // null = ilimitado\n\n  @@map(\"planes\")\n}\n\nmodel Propiedad {\n  id           String    @id @default(cuid())\n  titulo       String\n  ciudad       String\n  barrio       String    @default(\"\")\n  tipo         String // apartamento | casa | villa | loft | estudio\n  listing      String    @default(\"rent\") // rent | sale | rent_sale | vacation\n  precio       Int\n  estrato      Int?\n  habitaciones Int       @default(1)\n  banos        Int       @default(1)\n  metros       Int\n  parqueaderos Int       @default(0)\n  fotos        String    @default(\"[]\") // JSON array serializado\n  comodidades  String    @default(\"[]\") // JSON array serializado\n  video        String?\n  tourVirtual  Boolean   @default(false)\n  tourUrl      String?\n  tourTipo     String?\n  mapa2d       Boolean   @default(false)\n  destacado    Boolean   @default(false)\n  ownerId      String\n  createdAt    DateTime  @default(now())\n  updatedAt    DateTime  @updatedAt\n  deletedAt    DateTime?\n\n  owner     Usuario    @relation(\"OwnerProps\", fields: [ownerId], references: [id])\n  visitas   Visitas[]\n  mensajes  Mensaje[]\n  leads     Lead[]\n  pagos     Pago[]\n  favoritos Favorito[]\n\n  @@map(\"propiedades\")\n}\n\nmodel Visitas {\n  id          String   @id @default(cuid())\n  cliente     String\n  inquilinoId String?\n  propId      String\n  fecha       String\n  hora        String\n  estado      String   @default(\"pendiente\") // pendiente | confirmada | cancelada\n  nota        String?\n  createdAt   DateTime @default(now())\n\n  inquilino Propiedad @relation(fields: [propId], references: [id], onDelete: Cascade)\n  usuario   Usuario?  @relation(\"InquilinoVisitas\", fields: [inquilinoId], references: [id])\n\n  @@map(\"visitas\")\n}\n\nmodel Mensaje {\n  id        String   @id @default(cuid())\n  propId    String\n  deId      String\n  paraId    String\n  texto     String\n  leido     Boolean  @default(false)\n  createdAt DateTime @default(now())\n\n  propiedad Propiedad @relation(fields: [propId], references: [id], onDelete: Cascade)\n  de        Usuario   @relation(\"MensajesDe\", fields: [deId], references: [id])\n  para      Usuario   @relation(\"MensajesPara\", fields: [paraId], references: [id])\n\n  @@map(\"mensajes\")\n}\n\nmodel Lead {\n  id          String   @id @default(cuid())\n  nombre      String\n  email       String\n  propId      String\n  presupuesto String?\n  estado      String   @default(\"new\") // new | contactado | interesado | visita_agendada | lost\n  score       Int      @default(50)\n  fuente      String   @default(\"Portal\")\n  ownerId     String\n  createdAt   DateTime @default(now())\n  updatedAt   DateTime @updatedAt\n\n  propiedad Propiedad @relation(fields: [propId], references: [id], onDelete: Cascade)\n  owner     Usuario   @relation(\"OwnerLeads\", fields: [ownerId], references: [id])\n\n  @@map(\"leads\")\n}\n\nmodel Pago {\n  id          String   @id @default(cuid())\n  inquilinoId String\n  propId      String\n  ownerId     String\n  monto       Int\n  fecha       String\n  estado      String   @default(\"pendiente\") // pendiente | pagado | vencido\n  metodo      String?\n  wompiRef    String?\n  createdAt   DateTime @default(now())\n\n  inquilino Propiedad @relation(fields: [propId], references: [id], onDelete: Cascade)\n  inq       Usuario   @relation(\"InquilinoPagos\", fields: [inquilinoId], references: [id])\n  owner     Usuario   @relation(\"OwnerPagos\", fields: [ownerId], references: [id])\n\n  @@map(\"pagos\")\n}\n\nmodel Favorito {\n  id     String @id @default(cuid())\n  userId String\n  propId String\n\n  usuario   Usuario   @relation(fields: [userId], references: [id], onDelete: Cascade)\n  propiedad Propiedad @relation(fields: [propId], references: [id], onDelete: Cascade)\n\n  @@unique([userId, propId])\n  @@map(\"favoritos\")\n}\n\nmodel Suscripcion {\n  id        String    @id @default(cuid())\n  userId    String    @unique\n  planId    String    @default(\"free\")\n  estado    String    @default(\"activo\") // activo | cancelado | vencido\n  vence     DateTime?\n  wompiRef  String?\n  createdAt DateTime  @default(now())\n  updatedAt DateTime  @updatedAt\n\n  usuario Usuario @relation(fields: [userId], references: [id], onDelete: Cascade)\n\n  @@map(\"suscripciones\")\n}\n",
